// Counts are calculated from graded records, never generated by the language model.
export function summarizeEvidence(records) {
  const latest = new Map();
  for (const r of records) {
    const key = `${r.student_id}:${r.question_item_id}`;
    const prev = latest.get(key);
    if (!prev || new Date(r.submitted_at) > new Date(prev.submitted_at))
      latest.set(key, r);
  }
  const groups = new Map();
  for (const r of latest.values()) {
    const key = `${r.student_id}:${r.topic_id}`;
    if (!groups.has(key))
      groups.set(key, {
        studentId: r.student_id,
        studentName: r.student_name,
        topicId: r.topic_id,
        topic: r.topic,
        observations: 0,
        wrong: 0,
        attempts: new Set(),
        evidence: [],
      });
    const g = groups.get(key);
    g.observations++;
    if (!r.correct) g.wrong++;
    g.attempts.add(String(r.attempt_id));
    g.evidence.push(r);
  }
  return [...groups.values()].map((g) => ({
    ...g,
    attempts: g.attempts.size,
    errorRate: Math.round((g.wrong / g.observations) * 100),
    dataLevel:
      g.observations < 5 || g.attempts.size < 2
        ? "insufficient"
        : g.observations >= 10 && g.attempts.size >= 3
          ? "extended"
          : "preliminary",
    note: "Chỉ tính câu độc lập đã chấm trong 30 ngày; lấy lượt mới nhất của cùng câu. Chưa kiểm chứng độ bao phủ dạng bài.",
  }));
}
export async function classEvidence(db, user, sid, classId, subject, staff) {
  const r = await db.query(
    `SELECT a.student_id,u.name AS student_name,a.id AS attempt_id,a.assignment_id,a.submitted_at,
 q.question_item_id,n.id AS topic_id,n.name AS topic,i.id AS item_id,i.position,i.snapshot->>'stem' AS stem,
 aa.answer AS response,aa.correct
 FROM attempt_answers aa JOIN assessment_attempts a ON a.id=aa.attempt_id
 JOIN assessment_assignments assignment ON assignment.id=a.assignment_id AND assignment.school_id=a.school_id
 JOIN users u ON u.id=a.student_id JOIN assessment_items i ON i.id=aa.assessment_item_id
 JOIN question_versions q ON q.id=i.question_version_id JOIN curriculum_nodes n ON n.id=q.curriculum_node_id
 WHERE a.school_id=$1 AND assignment.class_id=$2 AND q.subject=$3 AND a.status='graded' AND aa.correct IS NOT NULL
 AND a.submitted_at>=now()-interval '30 days' AND ($4::boolean OR a.student_id=$5)
 ORDER BY a.submitted_at DESC,a.id DESC LIMIT 5001`,
    [sid, classId, subject, staff, user.id],
  );
  return {
    groups: summarizeEvidence(r.rows.slice(0, 5000)),
    truncated: r.rows.length > 5000,
  };
}
